mapper.update:
update fin_budget
set name = #{budget.name}, updated_at = now(3)
where id = #{budget.id}

mapper.select:
select month_key as yearMonth, metric_code as metricCode, metric_value as metricValue
from fin_metric_monthly
where user_id = #{userId}
  and month_key >= #{fromYm}
  and month_key <= #{toYm}
order by month_key, metric_code
